// AI generated by pi coding agent, v1.0
// ---------------------------------------------------------------------------
// uPlot wrapper for the measurement time series.
//
// Adapted from PIDDojo src/chart.ts (Martin Oberzalek, MIT): the ResizeObserver
// driven lifecycle, the theme palette handling and the "recreate the plot on
// theme change" approach are taken from there. Replaced the streaming ring
// buffer with a plain "setData" model, because the dashboard loads aggregated
// history instead of live samples.
// ---------------------------------------------------------------------------

import uPlot from 'uplot';
import 'uplot/dist/uPlot.min.css';

import type { Bucket, Field } from './types';
import { fieldMeta } from './types';

interface Palette {
  temp_inside: string;
  temp_outside: string;
  hum_inside: string;
  hum_outside: string;
  grid: string;
  axis: string;
  text: string;
  panel: string;
  line: string;
}

const PALETTES: Record<'light' | 'dark', Palette> = {
  dark: {
    temp_inside: '#ffb454',
    temp_outside: '#5cc8ff',
    hum_inside: '#c78bff',
    hum_outside: '#41d18b',
    grid: 'rgba(255, 255, 255, 0.08)',
    axis: '#8b96ad',
    text: '#e6ebf5',
    panel: '#111a2b',
    line: 'rgba(255, 255, 255, 0.14)',
  },
  light: {
    temp_inside: '#c46d00',
    temp_outside: '#1f6fd0',
    hum_inside: '#7b3fb5',
    hum_outside: '#12895a',
    grid: 'rgba(20, 30, 60, 0.09)',
    axis: '#5b667c',
    text: '#1c2333',
    panel: '#ffffff',
    line: 'rgba(20, 30, 60, 0.14)',
  },
};

/** Line colour of a measure column, for the chart and the HTML legend. */
export function seriesColor(field: Field, dark: boolean): string {
  return PALETTES[dark ? 'dark' : 'light'][field];
}

/** Smallest zoom window we allow, in seconds (10 minutes). */
const MIN_ZOOM_SPAN = 10 * 60;

// uPlot declares its axis sides as an ambient const enum, which cannot be used
// with `isolatedModules`. The numeric values are stable: 0 top, 1 right,
// 2 bottom, 3 left.
const SIDE_RIGHT = 1 as uPlot.Axis.Side;
const SIDE_LEFT = 3 as uPlot.Axis.Side;

// uPlot's built-in time axis is English ("12am", "11/9/26"). The dashboard is
// German, so the tick labels are formatted here, picking the resolution that
// matches the tick increment.
const TICK_FORMATS = {
  seconds: new Intl.DateTimeFormat('de-AT', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
  time: new Intl.DateTimeFormat('de-AT', { hour: '2-digit', minute: '2-digit' }),
  day: new Intl.DateTimeFormat('de-AT', { day: '2-digit', month: '2-digit' }),
  month: new Intl.DateTimeFormat('de-AT', { month: 'short', year: 'numeric' }),
};

const DAY = 86400;

/** Rough advance width of one axis glyph at the default 12px font. */
const AXIS_GLYPH_WIDTH = 6.5;

/**
 * Format one x axis tick depending on how far apart the ticks are.
 *
 * Wide windows (a full year or more) switch to "month + year" labels: with a
 * year view a bare "09.11." would not tell which year it belongs to.
 */
function formatTick(seconds: number, increment: number, wideSpan: boolean): string {
  const date = new Date(seconds * 1000);
  if (increment < 60) return TICK_FORMATS.seconds.format(date);
  if (increment < 12 * 3600) return TICK_FORMATS.time.format(date);
  if (wideSpan && increment >= 12 * 3600) return TICK_FORMATS.month.format(date);
  if (increment < 45 * DAY) return TICK_FORMATS.day.format(date);
  return TICK_FORMATS.month.format(date);
}

export class TimeSeriesChart {
  private plot: uPlot | null = null;
  private fields: Field[] = [];
  private xs: number[] = [];
  private columns: Array<Array<number | null>> = [];
  private dark = true;
  private bucket: Bucket = '1h';
  private bounds: { min: number; max: number } | null = null;
  private readonly observer: ResizeObserver;

  constructor(private readonly host: HTMLElement) {
    this.observer = new ResizeObserver(() => this.resize());
    this.observer.observe(host);
  }

  /**
   * Replace the whole data set.
   *
   * `keepZoom` must be false whenever the requested time window changes (a new
   * preset): keeping the previous x range would squeeze the new data into a
   * window that no longer matches it. It is true for the periodic refresh, where
   * a zoom the user made should survive.
   */
  setData(
    points: Array<{ t: number } & Partial<Record<Field, number | null>>>,
    fields: Field[],
    bucket: Bucket,
    keepZoom = false,
  ): void {
    const structureChanged =
      this.plot === null ||
      fields.length !== this.fields.length ||
      fields.some((f, i) => f !== this.fields[i]) ||
      bucket !== this.bucket;

    const xs = points.map((point) => point.t);
    const columns = fields.map((field) => points.map((point) => point[field] ?? null));

    const first = xs[0];
    const last = xs[xs.length - 1];
    const bounds =
      first === undefined || last === undefined ? null : { min: first, max: last };

    const plot = this.plot;

    // Ask about the zoom *before* this.bounds is replaced by the new window.
    const previousScale =
      keepZoom && plot && this.scaleIsZoomed(plot)
        ? { min: plot.scales.x?.min ?? 0, max: plot.scales.x?.max ?? 0 }
        : null;

    this.fields = [...fields];
    this.bucket = bucket;
    this.xs = xs;
    this.columns = columns;
    this.bounds = bounds;

    if (structureChanged || !plot) {
      this.build(false);
      return;
    }

    plot.setData(this.alignedData(), true);
    if (previousScale && previousScale.max > previousScale.min) {
      plot.setScale('x', previousScale);
    }
  }

  /** Switch between the light and the dark palette (rebuilds the plot). */
  setTheme(dark: boolean): void {
    if (dark === this.dark) return;
    this.dark = dark;
    // Only a palette change: the visible window must stay exactly where it is.
    this.build(true);
  }

  /** Restore the full data range after the user zoomed in. */
  resetZoom(): void {
    const u = this.plot;
    if (!u || !this.bounds) return;
    u.setScale('x', { ...this.bounds });
  }

  destroy(): void {
    this.observer.disconnect();
    this.plot?.destroy();
    this.plot = null;
  }

  // -- internals ------------------------------------------------------------

  private alignedData(): uPlot.AlignedData {
    return [this.xs, ...this.columns];
  }

  private build(keepScale: boolean): void {
    const previous = this.plot;

    // uPlot cannot change the series/axis layout in place, so a preset or theme
    // change rebuilds the instance. Only a theme change may carry the zoom over.
    const previousScale =
      keepScale && previous && this.scaleIsZoomed(previous)
        ? { min: previous.scales.x?.min ?? 0, max: previous.scales.x?.max ?? 0 }
        : null;

    previous?.destroy();
    this.plot = null;

    const palette = PALETTES[this.dark ? 'dark' : 'light'];
    const series: uPlot.Series[] = [{}];

    for (const field of this.fields) {
      const meta = fieldMeta(field);
      series.push({
        label: meta.unit ? `${meta.label} [${meta.unit}]` : meta.label,
        stroke: palette[field],
        width: 1.6,
        // Humidity is dashed so a temperature and a humidity line never look
        // like the same measurement when they cross.
        dash: meta.axis === 'hum' ? [5, 4] : undefined,
        scale: meta.axis,
        points: { show: false },
        value: (_u, v) => (v == null ? '–' : `${v.toFixed(meta.decimals)} ${meta.unit}`),
      });
    }

    const axisCommon: Partial<uPlot.Axis> = {
      stroke: palette.axis,
      grid: { stroke: palette.grid },
      ticks: { stroke: palette.grid },
    };

    // Only render the y axes that actually carry a series - an empty
    // "Luftfeuchte [%]" axis next to a pure temperature view is just noise.
    const hasTemp = this.fields.some((field) => fieldMeta(field).axis === 'temp');
    const hasHum = this.fields.some((field) => fieldMeta(field).axis === 'hum');

    const xAxis: uPlot.Axis = {
      ...axisCommon,
      values: (u, splits, _axisIdx, space, increment) => {
        const span = (u.scales.x?.max ?? 0) - (u.scales.x?.min ?? 0);
        const wideSpan = span > 300 * DAY;
        const labels = splits.map((value) => (value == null ? '' : formatTick(value, increment, wideSpan)));

        // uPlot sized the tick distance for its own (shorter) labels. Our German
        // "März 2026" is wider, so on narrow screens every n-th label is dropped
        // instead of letting them overlap.
        const longest = labels.reduce((max, label) => Math.max(max, label.length), 0);
        const needed = longest * AXIS_GLYPH_WIDTH;
        const stride = Math.max(1, Math.ceil(needed / Math.max(space, 1)));

        return stride === 1 ? labels : labels.map((label, index) => (index % stride === 0 ? label : ''));
      },
    };

    const axes: uPlot.Axis[] = [xAxis];

    if (hasTemp) {
      axes.push({
        ...axisCommon,
        scale: 'temp',
        side: SIDE_LEFT,
        label: 'Temperatur [°C]',
        labelSize: 16,
        size: 62,
      });
    }

    if (hasHum) {
      axes.push({
        ...axisCommon,
        scale: 'hum',
        side: SIDE_RIGHT,
        label: 'Luftfeuchte [%]',
        labelSize: 16,
        size: 62,
        grid: { show: false },
      });
    }

    const options: uPlot.Options = {
      width: Math.max(160, this.host.clientWidth),
      height: Math.max(200, this.host.clientHeight),
      legend: { show: false },
      scales: {
        x: { time: true },
        temp: { auto: true },
        hum: { auto: true, range: () => [0, 100] },
      },
      cursor: {
        drag: { x: true, y: false, setScale: true },
        points: { size: 6 },
      },
      axes,
      series,
    };

    const plot = new uPlot(options, this.alignedData(), this.host);
    this.plot = plot;
    this.attachInteractions(plot);

    // Keep the current window when only the theme changed.
    if (previousScale && previousScale.max > previousScale.min) {
      plot.setScale('x', previousScale);
    }
  }

  private scaleIsZoomed(u: uPlot): boolean {
    if (!this.bounds) return false;
    const min = u.scales.x?.min;
    const max = u.scales.x?.max;
    if (min == null || max == null) return false;
    return Math.abs(min - this.bounds.min) > 1 || Math.abs(max - this.bounds.max) > 1;
  }

  private attachInteractions(u: uPlot): void {
    // Wheel zoom: uPlot has drag-zoom built in but no wheel support.
    u.over.addEventListener('wheel', this.onWheel, { passive: false });
    u.over.addEventListener('dblclick', this.onDoubleClick);
  }

  private readonly onWheel = (event: WheelEvent): void => {
    const u = this.plot;
    if (!u || !this.bounds) return;

    const rect = u.over.getBoundingClientRect();
    if (rect.width <= 0) return;

    const min = u.scales.x?.min;
    const max = u.scales.x?.max;
    if (min == null || max == null) return;

    event.preventDefault();

    const anchor = u.posToVal(event.clientX - rect.left, 'x');
    const factor = event.deltaY > 0 ? 1.2 : 1 / 1.2;

    let nextMin = anchor - (anchor - min) * factor;
    let nextMax = anchor + (max - anchor) * factor;

    // Never zoom out past the loaded data, never zoom in past MIN_ZOOM_SPAN.
    nextMin = Math.max(nextMin, this.bounds.min);
    nextMax = Math.min(nextMax, this.bounds.max);
    if (nextMax - nextMin < MIN_ZOOM_SPAN) return;

    u.setScale('x', { min: nextMin, max: nextMax });
  };

  private readonly onDoubleClick = (event: MouseEvent): void => {
    event.preventDefault();
    this.resetZoom();
  };

  private resize(): void {
    const u = this.plot;
    if (!u) return;
    const width = this.host.clientWidth;
    const height = this.host.clientHeight;
    if (width <= 0 || height <= 0) return;
    u.setSize({ width, height });
  }
}
// End of AI generated by pi coding agent, v1.0
